#!/bin/sh
# P19 sweep driver: one binary per (PAGE_SIZE, TEST_FRAMES) layout, generated by sed from the one
# edited source so that the *constants* are the experiment and the C is never re-edited per layout.
# GUARDRAIL: PAGE_SIZE, PAGE_SHIFT and TEST_FRAMES must be changed together — P03f shipped a tree
# where PAGE_SIZE said 256 and flash_page still shifted by 9, which produced two page numbers for
# one address and a 217-retry false livelock. sed rewrites all three from one layout spec.
# GUARDRAIL: every run is bounded twice (internal SWEEP_DEADLINE + `timeout 30`) and redirected to
# a log, never piped through head — P03 lost the only copy of its hang position that way.
set -u
layout() {  # $1=tag $2=PAGE_SIZE $3=PAGE_SHIFT $4=FRAMES $5=dir $6=stem
  tag=$1; ps=$2; sh=$3; fr=$4; dir=$5; stem=$6
  sed -e "s/^#define PAGE_SIZE   256/#define PAGE_SIZE   $ps/" \
      -e "s/^#define PAGE_SIZE   512/#define PAGE_SIZE   $ps/" \
      -e "s/^#define PAGE_SHIFT  [0-9]*/#define PAGE_SHIFT  $sh/" \
      -e "s/^#define TEST_FRAMES    [0-9]*/#define TEST_FRAMES    $fr/" \
      "$dir/$stem.c" > "$dir/$stem-$tag.c"
  grep -q "PAGE_SIZE   $ps" "$dir/$stem-$tag.c" || echo "BUILD-BUG: page size not set in $tag"
  grep -q "TEST_FRAMES    $fr" "$dir/$stem-$tag.c" || echo "BUILD-BUG: frames not set in $tag"
  gcc -DHOST -DPAGING -std=c99 -O1 -Wall -Wextra -o "$dir/$stem-$tag" "$dir/$stem-$tag.c" 2> "$dir/build-$stem-$tag.log"
  echo "built $dir/$stem-$tag (page=$ps frames=$fr) gcc=$?"
}

for spec in "4x512 512 9 4" "3x512 512 9 3" "2x512 512 9 2" "4x256 256 8 4"; do
  set -- $spec
  layout "$1" "$2" "$3" "$4" . paging_sim
  layout "$1" "$2" "$3" "$4" rmw paging_sim
done
